// Definição de uma 'interface' de operações de arquivo
struct file_operations {
    ssize_t (*read) (struct file *, char __user *, size_t, loff_t *);
    ssize_t (*write)(struct file *, const char __user *, size_t, loff_t *);
    int     (*open) (struct inode *, struct file *);
    int     (*release)(struct inode *, struct file *);
    // ... dezenas de outras 'operações virtuais'
};

// Cada driver implementa sua própria versão (equivalente a 'override')
static const struct file_operations meu_driver_fops = {
    .read    = meu_driver_read,
    .write   = meu_driver_write,
    .open    = meu_driver_open,
    .release = meu_driver_release,
};

// A 'classe base' (dados comuns a todo dispositivo)
struct device {
    const char *name;
    struct device *parent;
    // ...
};

// A 'classe derivada' EMBUTE a base dentro de si
struct usb_device {
    struct device dev;   // <- herança por composição
    int devnum;
    // campos específicos de USB
};

// Macro que faz o 'upcast' inverso: de membro para struct completa
#define container_of(ptr, type, member) \
    ((type *)((char *)(ptr) - offsetof(type, member)))

// Uso: dado um struct device*, volta para o struct usb_device* original
struct usb_device *udev = container_of(dev_ptr, struct usb_device, dev);
